<?php

namespace App\Models\Concerns;

/**
 * The one containment check for files we keep outside the web root:
 * verification documents and careers CVs.
 *
 * Every consumer (the admin streaming routes, the delete paths, the CV
 * attachment on a careers email) goes through resolvePath(), so the check
 * cannot be forgotten by one of them, and a fix here reaches both stores.
 * Paths are generated by our own processors and never come from a request,
 * but a row is still data, and data can be wrong.
 *
 * The using model says where its files live with storageRoot().
 */
trait ResolvesStoredPath
{
    abstract public static function storageRoot(): string;

    /**
     * The absolute path of a stored file, or null when it is missing, is not
     * a regular file, or the stored value tries to leave the storage root
     * (`..`, a symlink out, a NUL byte).
     */
    public function resolvePath(string $path): ?string
    {
        $path = ltrim(trim($path), '/');
        if ($path === '' || str_contains($path, "\0")) {
            return null;
        }

        $root = realpath(static::storageRoot());
        if ($root === false) {
            return null;
        }
        $root = rtrim($root, '/');
        $full = realpath($root . '/' . $path);

        if ($full === false || ! str_starts_with($full, $root . '/') || ! is_file($full)) {
            return null;
        }

        return $full;
    }
}
